"""Cálculo de preços de um pedido."""


def _round_percent(amount, percentage):
    """Calcula uma percentagem inteira, arredondando meios para cima."""
    return (amount * percentage + 50) // 100


def _validate_items(items):
    if not isinstance(items, (list, tuple)) or not items:
        raise ValueError("items deve ser uma lista ou tupla não vazia")

    subtotal = 0
    for item in items:
        if not isinstance(item, dict):
            raise ValueError("cada item deve ser um dicionário")
        sku = item.get("sku")
        price = item.get("unit_price_cents")
        quantity = item.get("quantity")
        if not isinstance(sku, str) or not sku:
            raise ValueError("sku deve ser uma string não vazia")
        if isinstance(price, bool) or not isinstance(price, int) or price < 0:
            raise ValueError("unit_price_cents deve ser um inteiro não negativo")
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("quantity deve ser um inteiro positivo")
        subtotal += price * quantity
    return subtotal


def _validate_customer(customer):
    if not isinstance(customer, dict):
        raise ValueError("customer deve ser um dicionário")
    if "vip" in customer and not isinstance(customer["vip"], bool):
        raise ValueError("vip deve ser bool")


def _coupon_discount(remaining, coupon):
    if coupon is None:
        return 0
    if not isinstance(coupon, str):
        raise ValueError("coupon deve ser uma string ou None")
    normalized = coupon.strip().upper()
    if normalized == "SAVE10":
        return _round_percent(remaining, 10)
    if normalized == "FIXED500":
        return min(500, remaining)
    raise ValueError("cupom desconhecido")


def calculate_order(items, customer, coupon=None):
    """Retorna subtotal, descontos, imposto e total de um pedido."""
    subtotal = _validate_items(items)
    _validate_customer(customer)
    vip_discount = _round_percent(subtotal, 10) if customer.get("vip", False) else 0
    remaining = subtotal - vip_discount
    coupon_discount = _coupon_discount(remaining, coupon)
    taxable = remaining - coupon_discount
    tax = _round_percent(taxable, 10)
    return {
        "subtotal_cents": subtotal,
        "vip_discount_cents": vip_discount,
        "coupon_discount_cents": coupon_discount,
        "taxable_cents": taxable,
        "tax_cents": tax,
        "total_cents": taxable + tax,
    }
import unittest

from pricing import calculate_order


def item(sku, price, qty):
    return {"sku": sku, "unit_price_cents": price, "quantity": qty}


class PublicPricingTests(unittest.TestCase):
    def test_r8_result_keys(self):
        result = calculate_order([item("a", 1000, 1)], {})
        self.assertEqual(
            set(result),
            {"subtotal_cents", "vip_discount_cents", "coupon_discount_cents",
             "taxable_cents", "tax_cents", "total_cents"},
        )

    def test_r2_r5_plain_order(self):
        result = calculate_order([item("a", 1000, 2), item("b", 500, 1)], {})
        self.assertEqual(result["subtotal_cents"], 2500)
        self.assertEqual(result["tax_cents"], 250)
        self.assertEqual(result["total_cents"], 2750)

    def test_r3_vip_discount(self):
        result = calculate_order([item("a", 10000, 1)], {"vip": True})
        self.assertEqual(result["vip_discount_cents"], 1000)
        self.assertEqual(result["taxable_cents"], 9000)

    def test_r4_save10_discount_amount(self):
        result = calculate_order([item("a", 10000, 1)], {}, "SAVE10")
        self.assertEqual(result["coupon_discount_cents"], 1000)

    def test_percentages_round_half_up_individually(self):
        result = calculate_order([item("a", 5, 1)], {"vip": True}, "SAVE10")
        self.assertEqual(result["vip_discount_cents"], 1)
        self.assertEqual(result["coupon_discount_cents"], 0)
        self.assertEqual(result["taxable_cents"], 4)
        self.assertEqual(result["tax_cents"], 0)

    def test_fixed_coupon_is_limited_and_normalized(self):
        result = calculate_order([item("a", 300, 1)], {}, "  fixed500 ")
        self.assertEqual(result["coupon_discount_cents"], 300)
        self.assertEqual(result["taxable_cents"], 0)

    def test_invalid_inputs_raise_value_error(self):
        invalid_orders = [
            ([], {}),
            ([item("", 1, 1)], {}),
            ([item("a", True, 1)], {}),
            ([item("a", 1, False)], {}),
            ([item("a", 1, 1)], {"vip": 1}),
        ]
        for args in invalid_orders:
            with self.subTest(args=args):
                with self.assertRaises(ValueError):
                    calculate_order(*args)
        with self.assertRaises(ValueError):
            calculate_order([item("a", 1, 1)], {}, "NOPE")
        with self.assertRaises(ValueError):
            calculate_order([item("a", 1, 1)], {}, 10)

    def test_inputs_are_not_modified(self):
        items = [item("b", 100, 1), item("a", 200, 2)]
        original_items = [dict(entry) for entry in items]
        customer = {"vip": True}
        calculate_order(items, customer, "save10")
        self.assertEqual(items, original_items)
        self.assertEqual(customer, {"vip": True})


if __name__ == "__main__":
    unittest.main()
